import os
import boto3

def extract_table_cells(file_path: str):
    textract = boto3.client("textract")

    with open(file_path, "rb") as f:
        response = textract.analyze_document(
            Document={"Bytes": f.read()},
            FeatureTypes=["TABLES"]
        )

    blocks = response["Blocks"]
    block_map = {block["Id"]: block for block in blocks}
    tables = []

    for block in blocks:
        if block["BlockType"] == "TABLE":
            cell_map = {}
            max_row = 0
            max_col = 0

            for rel in block.get("Relationships", []):
                if rel["Type"] == "CHILD":
                    for cell_id in rel["Ids"]:
                        cell_block = block_map.get(cell_id)
                        if cell_block and cell_block["BlockType"] == "CELL":
                            row_idx = cell_block["RowIndex"]
                            col_idx = cell_block["ColumnIndex"]

                            max_row = max(max_row, row_idx)
                            max_col = max(max_col, col_idx)

                            text_parts = []
                            for c_rel in cell_block.get("Relationships", []):
                                if c_rel["Type"] == "CHILD":
                                    for child_id in c_rel["Ids"]:
                                        word_block = block_map.get(child_id)
                                        if word_block and word_block.get("Text"):
                                            text_parts.append(word_block["Text"])

                            cell_map[(row_idx, col_idx)] = " ".join(text_parts)

            grid = []
            for r in range(1, max_row + 1):
                row_data = [cell_map.get((r, c), "") for c in range(1, max_col + 1)]
                grid.append(row_data)
            tables.append(grid)

    return tables
